<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require_business_portal_access();
require __DIR__.'/../app/BusinessClaimService.php';
require __DIR__.'/../app/BusinessAccountPortalService.php';
function claim_lower(string $value):string{return function_exists('mb_strtolower')?mb_strtolower($value,'UTF-8'):strtolower($value);}
$service=new BusinessClaimService(db());$error='';$success=false;
$account=empty($_SESSION['business_account_id'])?null:(new BusinessAccountPortalService(db()))->current((int)$_SESSION['business_account_id']);
try{
    if($_SERVER['REQUEST_METHOD']==='POST'){
        csrf();
        if(!ready())throw new RuntimeException('La recepción de solicitudes no está habilitada en este momento.');
        $service->submit($_POST);$success=true;
    }
}catch(Throwable $exception){if(class_exists('PortalIncidents',false))PortalIncidents::technical($exception,'reclamar_negocio');$error=$exception instanceof PDOException?'No se pudo guardar la solicitud. Vuelve a intentarlo más tarde.':$exception->getMessage();http_response_code(400);}
$destinations=$service->destinations();$destinationId=max(0,(int)($_GET['destino']??$_POST['destination_id']??0));
$destinationIds=array_map(static fn($row)=>(int)$row['id'],$destinations);if(!in_array($destinationId,$destinationIds,true))$destinationId=0;
$categories=$destinationId?$service->categories($destinationId):[];$category=(string)($_GET['categoria']??$_POST['category_code']??'');
$categoryCodes=array_column($categories,'code');if(!in_array($category,$categoryCodes,true))$category='';
$name=trim((string)($_GET['nombre']??$_POST['nombre']??''));$results=$destinationId&&$category?$service->search($destinationId,$category,$name):[];
if(($_GET['search']??'')==='1'){
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    echo json_encode(['results'=>$results],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);exit;
}
require_once __DIR__.'/_account-page.php';account_page(false);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Reclama tu negocio | Explorando Lugares</title><link rel="stylesheet" href="../assets/style.css?v=claim-search-2"></head><body><main class="wrap admin-page business-claim-page"><a class="brand" href="../index.html"><span>Explorando<b>Lugares</b></span></a><p><a href="../negocios-locales/interes/">← Negocios locales</a></p><h1>¿Tu negocio ya aparece?</h1><p>Busca el destino y la categoría para encontrarlo. Si no está en el listado, puedes registrar tu interés desde negocios locales.</p>
<?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if($success):?><p class="notice" role="status"><strong>Recibimos tu solicitud.</strong> El negocio quedó marcado como en trámite mientras revisamos tu relación con el establecimiento. Esto no crea una cuenta ni publica cambios. Te contactaremos usando los datos que indicaste.</p><?php else:?>
<form method="get" class="destination-editor business-claim-filters"><div class="destination-form-grid"><label>Destino<select name="destino" required data-submit-on-change><option value="">Selecciona un destino</option><?php foreach($destinations as $item):?><option value="<?=esc($item['id'])?>" <?=$destinationId===(int)$item['id']?'selected':''?>><?=esc($item['display_name'])?></option><?php endforeach ?></select></label><label>Categoría<select name="categoria" required data-submit-on-change <?=$destinationId?'':'disabled'?>><option value="">Selecciona una categoría</option><?php foreach($categories as $item):?><option value="<?=esc($item['code'])?>" <?=$category===$item['code']?'selected':''?>><?=esc($item['label'])?></option><?php endforeach ?></select></label><label class="wide">Filtrar por nombre<input name="nombre" value="<?=esc($name)?>" placeholder="Escribe el nombre del negocio" <?=$category?'':'disabled'?>></label></div><button class="pill" type="submit">Buscar negocios</button></form>
<?php if($destinationId&&$category):?>
<section class="destination-admin-list business-claim-results"><h2>Resultados <small id="business-claim-result-count">(<?=count($results)?> encontrados, máximo 500)</small></h2>
<div class="business-claim-result-list" id="business-claim-results"><?php foreach($results as $result):?><label class="business-claim-result" data-business-name="<?=esc(claim_lower($result['display_name']))?>"><input type="radio" name="business_id" form="business-claim-form" value="<?=esc($result['id'])?>" required><span><strong><?=esc($result['display_name'])?></strong><small><?=esc($result['information_status']==='VERIFICADO'?'Información verificada':'Información pública por confirmar')?><?=trim((string)$result['address_text'])?' · '.esc($result['address_text']):''?></small></span></label><?php endforeach ?></div>
<p class="business-claim-empty" id="business-claim-empty" <?=$results?'hidden':''?>>No encontramos negocios sin reclamar con esos filtros. Si no aparece, regístralo como un negocio nuevo.</p></section>
<?php if($account):?><form method="post" class="destination-editor business-claim-form" id="business-claim-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="destination_id" value="<?=esc($destinationId)?>"><input type="hidden" name="category_code" value="<?=esc($category)?>"><fieldset><legend>Solicitar la reclamación</legend><p>Enviarás la solicitud como <strong><?=esc($account['display_name'])?></strong> (<?=esc($account['email'])?>). Revisaremos la relación antes de autorizar la administración del negocio o cambiar la ficha pública.</p><div class="destination-form-grid"><label>Relación con el negocio<select name="relationship_code" required><option value="">Selecciona</option><option value="owner">Soy propietario/a</option><option value="authorized_representative">Represento al negocio</option><option value="other">Otra relación</option></select></label><label>Teléfono de contacto<input type="tel" name="phone" maxlength="40" autocomplete="tel"></label><label class="wide">Información adicional<textarea name="message" rows="3" maxlength="1000" placeholder="Cuéntanos cómo podemos verificar tu relación con el negocio"></textarea></label><label class="wide admin-checkbox-field"><span>Autorizo el uso de mis datos de cuenta y esta información para revisar y responder la solicitud. Acepto la <a href="../privacidad/" target="_blank" rel="noopener">política de tratamiento de datos</a>.</span><input type="checkbox" name="consent" value="1" required></label></div></fieldset><button class="pill" type="submit" id="business-claim-submit" <?=$results?'':'disabled'?>>Enviar solicitud de reclamación</button></form><?php else:?><aside class="notice"><strong>Para reclamar un negocio necesitas una cuenta empresarial.</strong><p>La cuenta no confirma que seas su representante. El equipo revisará esa relación antes de habilitar cambios o publicar información.</p><a class="pill" href="<?=esc(site_path('/negocios/registro/'))?>">Crear cuenta</a> <a class="pill light" href="<?=esc(site_path('/negocios/acceso/'))?>">Iniciar sesión</a></aside><?php endif ?><?php endif ?><?php endif ?>
<p><a href="../negocios-locales/interes/">¿No aparece tu negocio? Registra tu interés aquí ↗</a></p></main><script src="../assets/business-claim-filter.js?v=claim-search-2" defer></script></body></html>
